async function broadcastRecommendedForUser(userId: string) {
  const items = await getRecommendedItems(userId);
  const snapshot = JSON.stringify(items);
  if (lastRecommendedSnapshot.get(userId) !== snapshot) {
    lastRecommendedSnapshot.set(userId, snapshot);
    io.to(`user:${userId}`).emit("recommended:update", items);
  }
}

edits.replace:
async function broadcastRecommendedForUser(userId: string | null) {
  const items = await getRecommendedItems(userId);
  const snapshot = JSON.stringify(items);
  const audience = userId ?? "visitors";
  if (lastRecommendedSnapshot.get(audience) !== snapshot) {
    lastRecommendedSnapshot.set(audience, snapshot);
    io.to(userId ? `user:${userId}` : "visitors").emit("recommended:update", items);
  }
}

